    /**
     * Method to retrieve the Dependent via DependentFetchOneSummary
     * @param 	summary DependentFetchOneSummary 
     * @return 	DependentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Dependent getDependent( DependentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DependentFetchOneSummary arg cannot be null" );
    	
    	Dependent entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Dependent
        	// --------------------------------------
        	CompletableFuture<Dependent> futureEntity = queryGateway.query(new FindDependentQuery( new LoadDependentFilter( summary.getDependentId() ) ), ResponseTypes.instanceOf(Dependent.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Dependent with id " + summary.getDependentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


